---
name: Docs

# Versioned docs site (mike): `latest` tracks main, one frozen copy per release tag
# (v1.x.y), all living under docs/ on the gh-pages branch that mike maintains. The
# marketing page occupies the Pages ROOT beside it. Pages still deploys from a
# workflow artifact — the gh-pages branch is mike's ledger, not the Pages source —
# so publishing = mike commit → check the branch out → add marketing/ → upload.
on:
  push:
    branches: [main]
    # Path filters are not evaluated for tag pushes, so a release tag always publishes.
    tags: ["v*"]
    paths:
      - docs/site/**
      - docs/hooks/**
      - docs/overrides/**
      - marketing/**
      - mkdocs.yml
      - requirements-docs.txt
      - .github/workflows/docs.yml
  pull_request:
    paths:
      - docs/site/**
      - docs/hooks/**
      - docs/overrides/**
      - marketing/**
      - mkdocs.yml
      - requirements-docs.txt
      - .github/workflows/docs.yml
  workflow_dispatch:

permissions:
  contents: write # mike commits to gh-pages
  pages: write
  id-token: write

concurrency:
  group: pages
  cancel-in-progress: false

env:
  DISABLE_MKDOCS_2_WARNING: "true"

jobs:
  build:
    runs-on: ubuntu-latest
    outputs:
      version: ${{ steps.version.outputs.name }}
    steps:
      - uses: actions/checkout@v7

      - uses: actions/setup-python@v7
        with:
          python-version: "3.13"

      - run: pip install -r requirements-docs.txt

      # Every build (PRs included) must be strict-clean before anything is published.
      - run: mkdocs build --strict

      - name: Resolve the version to publish
        if: github.event_name != 'pull_request'
        id: version
        run: |
          if [[ "$GITHUB_REF" == refs/tags/v* ]]; then
            echo "name=${GITHUB_REF#refs/tags/}" >> "$GITHUB_OUTPUT"
            echo "title=${GITHUB_REF#refs/tags/}" >> "$GITHUB_OUTPUT"
          else
            echo "name=latest" >> "$GITHUB_OUTPUT"
            echo "title=latest (main)" >> "$GITHUB_OUTPUT"
          fi

      - name: Publish this version to gh-pages (mike)
        if: github.event_name != 'pull_request'
        # The tag name reaches the shell through env, never interpolated into the script.
        env:
          MIKE_VERSION: ${{ steps.version.outputs.name }}
          MIKE_TITLE: ${{ steps.version.outputs.title }}
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "41898282+github-actions[bot]@users.noreply.github.com"
          git fetch origin gh-pages --depth=1 || true
          mike deploy --push --deploy-prefix docs --title "$MIKE_TITLE" "$MIKE_VERSION"
          mike set-default --push --deploy-prefix docs latest

      - name: Assemble the Pages artifact (gh-pages + marketing root)
        if: github.event_name != 'pull_request'
        env:
          MIKE_VERSION: ${{ steps.version.outputs.name }}
        run: |
          rm -rf site && mkdir site
          # Fetch again so the artifact is built from what mike just pushed, whatever the
          # remote-tracking ref says.
          git fetch origin gh-pages --depth=1
          git --work-tree=site checkout FETCH_HEAD -- docs
          git reset -q # the checkout above stages the paths; leave the index clean
          test -f "site/docs/$MIKE_VERSION/index.html" || {
            echo "::error::docs/$MIKE_VERSION is not in the artifact about to be deployed"
            exit 1
          }
          cp -r marketing/. site/

      - uses: actions/upload-pages-artifact@v5
        if: github.event_name != 'pull_request'
        with:
          path: site

  deploy:
    needs: build
    if: github.event_name != 'pull_request'
    runs-on: ubuntu-latest
    environment:
      name: github-pages
      url: ${{ steps.deployment.outputs.page_url }}
    steps:
      - id: deployment
        uses: actions/deploy-pages@v5

      # A deploy that reports success is not proof the version is being served (#2392: the
      # v1.2.0 tag's run was green while /docs/v1.2.0/ returned 404).
      - name: The published version is live
        env:
          PAGE_URL: ${{ steps.deployment.outputs.page_url }}
          VERSION: ${{ needs.build.outputs.version }}
        run: |
          for attempt in $(seq 1 20); do
            if curl -fsS "${PAGE_URL%/}/docs/versions.json?run=${GITHUB_RUN_ID}-${attempt}" \
                | grep -q "\"version\": \"${VERSION}\""; then
              echo "docs/${VERSION} is live"
              exit 0
            fi
            sleep 15
          done
          echo "::error::docs/${VERSION} is not in the live versions.json after 5 minutes"
          exit 1
---
import { configDefaults, defineConfig } from 'vitest/config';
import react from '@vitejs/plugin-react';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));

// Proxy target for /api and /mcp. Defaults to localhost:8000 for host-side dev
// (`pnpm dev`); the docker-compose frontend service overrides it to the in-network
// api hostname (http://api:8000), since `localhost` inside the container is the
// frontend container itself.
const apiProxyTarget = process.env.VITE_API_PROXY_TARGET || 'http://localhost:8000';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: {
      '@': resolve(__dirname, 'src'),
    },
  },
  server: {
    port: 3000,
    proxy: {
      '/api': apiProxyTarget,
      '/mcp': apiProxyTarget,
    },
  },
  build: {
    rollupOptions: {
      output: {
        // Split the heavy, rarely-changing vendors into their own long-cache
        // chunks so the app chunk stays small and an app change doesn't bust the
        // whole vendor bundle. Routes are additionally lazy-split (App.tsx).
        manualChunks(id: string) {
          if (!id.includes('node_modules')) return undefined;
          if (id.includes('/antd/') || id.includes('@ant-design/')) return 'antd';
          if (id.includes('@azure/')) return 'msal';
          // Monaco is huge (~4 MB) and only used by the custom-SQL editor — keep
          // it in its own chunk so the catch-all `vendor` doesn't pull it eagerly;
          // it's reached only via the React.lazy SqlEditorField (ADR 0019).
          if (id.includes('monaco-editor') || id.includes('@monaco-editor/')) return 'monaco';
          // recharts (+ its d3 deps) is only used by the dashboard chart widgets,
          // which live on lazy routes. Keep it out of the catch-all `vendor` chunk
          // (which loads eagerly) so it ships only when a chart route loads, like
          // monaco above (ADR 0022).
          if (
            id.includes('/recharts/') ||
            id.includes('/victory-vendor/') ||
            id.includes('/d3-') ||
            id.includes('/internmap/')
          ) {
            return 'recharts';
          }
          if (
            id.includes('/react/') ||
            id.includes('/react-dom/') ||
            id.includes('/react-router') ||
            id.includes('/scheduler/')
          ) {
            return 'react';
          }
          return 'vendor';
        },
      },
    },
  },
  test: {
    globals: true,
    environment: 'jsdom',
    // Slow shared CI runners push heavy antd+userEvent page tests past the 5s
    // default (#573 class; two distinct tests flaked 2026-08-01 — #1123). A slow
    // runner is an environment property, not a per-test one, so the allowance is
    // CI-gated here; locally the 5s default stays so a genuinely hung test still
    // fails fast during development.
    testTimeout: process.env.CI ? 15_000 : 5_000,
    setupFiles: ['./tests/setup.ts'],
    // Playwright specs live in e2e/ + e2e-otp/ + e2e-live/ and run under
    // `pnpm e2e`, not Vitest — they import @playwright/test and drive a browser,
    // so keep Vitest out of them. (Miss one and it fails with Playwright's
    // "did not expect test() to be called here", which reads like a version
    // conflict and is really just the wrong runner.)
    exclude: [...configDefaults.exclude, 'e2e/**', 'e2e-otp/**', 'e2e-docs/**', 'e2e-live/**'],
    coverage: {
      provider: 'v8',
      reporter: ['text', 'lcov'],
      // Count ALL of src, not just files the tests happen to import — otherwise
      // a new untested page silently doesn't lower the number and the threshold
      // gates nothing. main.tsx is the one exclusion: the DOM bootstrap can't
      // mount under the test runner (it *is* the thing that starts the app).
      // Consciously waived with it: the missing-#root throw and the bootstrap()
      // catch-fallback panel (its substantive callback logic,
      // completeSigninIfCallback, is covered in tests/auth/authClient.test.ts).
      include: ['src'],
      exclude: ['src/main.tsx'],
      thresholds: {
        // The 80% line gate (fails `pnpm test:coverage`, wired into CI since v1 W8).
        lines: 80,
      },
    },
  },
});
---
import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { BrowserRouter } from 'react-router-dom';

import { App } from './App';
import { ThemedShell } from './ThemedShell';
import { AuthProvider } from './auth/AuthProvider';
import { CurrentUserProvider } from './auth/CurrentUserProvider';
import { MeProvider } from './auth/MeProvider';
import { OtpSessionProvider } from './auth/OtpSessionProvider';
import { completeSigninIfCallback } from './auth/authClient';
import { ErrorBoundary } from './components/ErrorBoundary';
import { ThemeModeProvider } from './themeMode/ThemeModeProvider';
// Self-hosted fonts (visual-fidelity pass, ADR 0022) — Inter for UI text, JetBrains Mono for
// code/SQL/identifiers.
import '@fontsource/inter/latin-400.css';
import '@fontsource/inter/latin-500.css';
import '@fontsource/inter/latin-600.css';
import '@fontsource/inter/latin-700.css';
import '@fontsource/jetbrains-mono/latin-400.css';
import '@fontsource/jetbrains-mono/latin-500.css';
import './styles.css';

const maybeRoot = document.getElementById('root');
if (!maybeRoot) {
  throw new Error('Root element #root not found in index.html');
}
const rootEl: HTMLElement = maybeRoot;

// Auth lifecycle (issue #62, generic OIDC per ADR 0028): if this load is the IdP redirect back,
// complete the code exchange BEFORE React renders so the first paint reflects post-login state.
async function bootstrap() {
  await completeSigninIfCallback();
  createRoot(rootEl).render(
    <StrictMode>
      <ThemeModeProvider>
        <ThemedShell>
          <ErrorBoundary>
            <AuthProvider>
              {/* OTP session (ADR 0032) — above CurrentUserProvider, which derives
                  the signed-in user from it in `otp` mode. A passthrough in every
                  other mode, so no /me probe races the OIDC token acquisition. */}
              <OtpSessionProvider>
                <CurrentUserProvider>
                  <MeProvider>
                    <BrowserRouter>
                      <App />
                    </BrowserRouter>
                  </MeProvider>
                </CurrentUserProvider>
              </OtpSessionProvider>
            </AuthProvider>
          </ErrorBoundary>
        </ThemedShell>
      </ThemeModeProvider>
    </StrictMode>,
  );
}

bootstrap().catch((err) => {
  console.error('Auth bootstrap failed', err);
  rootEl.innerHTML =
    '<pre style="padding:24px;color:#a00">Authentication bootstrap failed. See console.</pre>';
});
