import { useMemo, type ReactNode } from 'react';

import { useAuthUser } from './authContext';
import { authMode, DEV_USER } from './config';
import { CurrentUserContext, type CurrentUser } from './currentUserContext';
import { useOtpSession } from './otpSessionContext';

/**
 * Provides the current user to the tree. - dev_bypass: static dev user. - unconfigured: null
 * (AuthGate shows the banner). - real: derives from the OIDC user (useAuthUser). - otp: derives
 */
export function CurrentUserProvider({ children }: { children: ReactNode }) {
  if (authMode === 'dev_bypass') {
    return <CurrentUserContext.Provider value={DEV_USER}>{children}</CurrentUserContext.Provider>;
  }
  if (authMode === 'real') {
    return <RealCurrentUserProvider>{children}</RealCurrentUserProvider>;
  }
  if (authMode === 'otp') {
    return <OtpCurrentUserProvider>{children}</OtpCurrentUserProvider>;
  }
  return <CurrentUserContext.Provider value={null}>{children}</CurrentUserContext.Provider>;
}

/** The OTP identity. */
function OtpCurrentUserProvider({ children }: { children: ReactNode }) {
  const { state } = useOtpSession();
  const me = state.status === 'signed_in' ? state.me : null;
  const value = useMemo<CurrentUser | null>(() => {
    if (!me) return null;
    return {
      name: me.display_name ?? me.email,
      username: me.email,
      homeAccountId: me.id,
      isDev: false,
    };
  }, [me]);
  return <CurrentUserContext.Provider value={value}>{children}</CurrentUserContext.Provider>;
}

function RealCurrentUserProvider({ children }: { children: ReactNode }) {
  const user = useAuthUser();
  const value = useMemo<CurrentUser | null>(() => {
    if (!user) return null;
    const profile = user.profile;
    const username = profile.preferred_username ?? profile.email ?? profile.sub;
    return {
      name: typeof profile.name === 'string' ? profile.name : '(unknown)',
      username,
      homeAccountId: profile.sub,
      isDev: false,
    };
  }, [user]);
  return <CurrentUserContext.Provider value={value}>{children}</CurrentUserContext.Provider>;
}
import { expect, type Page } from '@playwright/test';

/** Wait until the page has stopped loading. A route's landmark can be visible while a table
 * inside it is still behind its `loading` Spin, so the rows a scan should judge are not in the
 * DOM yet and the scan passes vacuously. Also lets mount transitions finish, which otherwise
 * get sampled mid-colour. */
export async function settle(page: Page): Promise<void> {
  await expect(page.locator('.ant-spin-spinning, .ant-skeleton-active')).toHaveCount(0);
  await page.evaluate(() =>
    Promise.all(
      document
        .getAnimations()
        .filter((a) => a.effect?.getComputedTiming().iterations !== Infinity)
        .map((a) => a.finished.catch(() => undefined)),
    ),
  );
}
import '@testing-library/jest-dom';

// antd's responsive components (Descriptions, Card, …) call window.matchMedia,
// which jsdom does not implement. Provide a no-op stub so they render in tests.
if (!window.matchMedia) {
  window.matchMedia = (query: string): MediaQueryList =>
    ({
      matches: false,
      media: query,
      onchange: null,
      addListener: () => {},
      removeListener: () => {},
      addEventListener: () => {},
      removeEventListener: () => {},
      dispatchEvent: () => false,
    }) as MediaQueryList;
}

// antd's Select/virtual-list (rc-virtual-list) uses ResizeObserver, absent in
// jsdom. A no-op stub lets dropdown options render in tests.
if (!window.ResizeObserver) {
  window.ResizeObserver = class {
    // Same arity as the real constructor; the callback is kept but never invoked.
    constructor(readonly callback: ResizeObserverCallback) {}
    observe(): void {}
    unobserve(): void {}
    disconnect(): void {}
  };
}
