export function fixtureKey(method: string, url: string): string {
  const { path, params } = split(url);
  const query = params.map(([k, v]) => `${k}=${v}`).join('&');
  return `${method.toUpperCase()} ${path}${query ? `?${query}` : ''}`;
}

/** The exact recording, else the same path's recording that shares the most query parameters. */
export function lookup(bundle: FixtureBundle, method: string, url: string): Lookup | null {
  const key = fixtureKey(method, url);
  const exact = bundle.entries[key];
  if (exact) return { response: exact, approximate: false };

  const { path, params } = split(url);
  const wanted = new Set(params.map(([k, v]) => `${k}=${v}`));
  const prefix = `${method.toUpperCase()} ${path}`;
  let best: { response: RecordedResponse; shared: number; extra: number } | null = null;
  for (const [candidate, response] of Object.entries(bundle.entries)) {
    if (candidate !== prefix && !candidate.startsWith(`${prefix}?`)) continue;
    const have = candidate.length > prefix.length ? candidate.slice(prefix.length + 1).split('&') : [];
    const shared = have.filter((p) => wanted.has(p)).length;
    const extra = have.length - shared;
    if (!best || shared > best.shared || (shared === best.shared && extra < best.extra)) {
      best = { response, shared, extra };
    }
  }
  return best ? { response: best.response, approximate: true } : null;
}

function shiftDate(isoDate: string, days: number): string {
  const moved = new Date(Date.parse(`${isoDate}T00:00:00Z`) + days * DAY_MS);
  return moved.toISOString().slice(0, 10);
}

/**
 * Move every date in a recorded payload forward by whole days, so data recorded last week still
 * reads as recent. Whole days keep date-only and timestamp fields consistent with each other.
 */
export function shiftDates<T>(value: T, days: number): T {
  if (days === 0) return value;
  if (typeof value === 'string') {
    if (ISO_DATE.test(value)) return shiftDate(value, days) as T;
    if (ISO_DATETIME.test(value)) return (shiftDate(value.slice(0, 10), days) + value.slice(10)) as T;
    return value;
  }
  if (Array.isArray(value)) return value.map((v) => shiftDates(v, days)) as T;
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([k, v]) => [k, shiftDates(v, days)]),
    ) as T;
  }
  return value;
}

/** Whole days between the recording and `now`; never negative. */
export function daysSince(capturedAt: string, now: number = Date.now()): number {
  const captured = Date.parse(capturedAt);
  if (Number.isNaN(captured)) return 0;
  return Math.max(0, Math.floor((now - captured) / DAY_MS));
}

import axios, {
  AxiosError,
  type AxiosAdapter,
  type AxiosResponse,
  type InternalAxiosRequestConfig,
} from 'axios';

import { daysSince, lookup, shiftDates, type FixtureBundle } from './fixtures';
import { announce } from './notices';

export const READ_ONLY_MESSAGE =
  'This is a read-only demo. Install DataQ to run it against your own data.';
export const NOT_RECORDED_MESSAGE = 'This view is not part of the read-only demo.';

function respond(
  config: InternalAxiosRequestConfig,
  status: number,
  data: unknown,
): Promise<AxiosResponse> {
  const response: AxiosResponse = {
    data,
    status,
    statusText: '',
    headers: { 'content-type': 'application/json' },
    config,
    request: {},
  };
  const ok = config.validateStatus ? config.validateStatus(status) : status >= 200 && status < 300;
  if (ok) return Promise.resolve(response);
  return Promise.reject(
    new AxiosError(
      `Request failed with status code ${status}`,
      status >= 500 ? AxiosError.ERR_BAD_RESPONSE : AxiosError.ERR_BAD_REQUEST,
      config,
      response.request,
      response,
    ),
  );
}

const envelope = (code: string, message: string) => ({ error: { code, message } });

/**
 * An axios adapter that answers from recorded responses and never touches the network. Reads
 * replay the recording; anything that would change state is refused.
 */
export function createDemoAdapter(load: () => Promise<FixtureBundle>): AxiosAdapter {
  return async (config) => {
    const method = (config.method ?? 'get').toUpperCase();
    if (method !== 'GET') {
      announce('read-only');
      return respond(config, 403, envelope('demo_read_only', READ_ONLY_MESSAGE));
    }
    const bundle = await load();
    const found = lookup(bundle, method, axios.getUri(config));
    if (!found) {
      announce('not-recorded');
      return respond(config, 404, envelope('demo_not_recorded', NOT_RECORDED_MESSAGE));
    }
    if (found.approximate) announce('approximate');
    const { status, data } = found.response;
    return respond(config, status, shiftDates(data, daysSince(bundle.capturedAt)));
  };
}

/** What the demo could not do for the visitor — raised by the adapter, shown by `DemoBadge`. */
export type DemoNotice = 'read-only' | 'not-recorded' | 'approximate';

export const DEMO_NOTICE_EVENT = 'dataq-demo-notice';

export function announce(kind: DemoNotice): void {
  window.dispatchEvent(new CustomEvent<DemoNotice>(DEMO_NOTICE_EVENT, { detail: kind }));
}

import { api } from '../api/client';
import { createDemoAdapter } from './adapter';
import type { FixtureBundle } from './fixtures';

/** True only in the static demo build (`pnpm build:demo`, #2419). A build-time constant. */
export const IS_DEMO = import.meta.env.VITE_DEMO === 'true';

export const INSTALL_GUIDE_URL =
  'https://theurgicduke771.github.io/DataQ/docs/latest/get-started/install/';

export const FIXTURES_FILE = 'demo-fixtures.json';

/** Point the shared API client at the recorded responses published beside the bundle. */
export function installDemo(baseUrl: string = import.meta.env.BASE_URL): void {
  let bundle: Promise<FixtureBundle> | undefined;
  const load = () => {
    bundle ??= fetch(`${baseUrl}${FIXTURES_FILE}`).then((res) => {
      if (!res.ok) throw new Error(`demo fixtures failed to load (${res.status})`);
      return res.json() as Promise<FixtureBundle>;
    });
    return bundle;
  };
  api.defaults.adapter = createDemoAdapter(load);
}

import { App, Flex, Tag, Typography } from 'antd';
import { useEffect } from 'react';

import { NOT_RECORDED_MESSAGE } from './adapter';
import { INSTALL_GUIDE_URL } from './index';
import { DEMO_NOTICE_EVENT, type DemoNotice } from './notices';

const INSTALL_LINK = (
  <a href={INSTALL_GUIDE_URL} target="_blank" rel="noreferrer">
    Run DataQ yourself in 5 minutes
  </a>
);

const NOTICES: Record<DemoNotice, { title: string; body: string }> = {
  'read-only': {
    title: 'Read-only demo',
    body: 'Nothing was changed. Saving, running and testing need a real DataQ.',
  },
  'not-recorded': { title: 'Not in the demo', body: NOT_RECORDED_MESSAGE },
  approximate: {
    title: 'Showing the default view',
    body: 'The demo replays recorded responses, so this filter or page is not applied.',
  },
};

/** The shell's "this is a demo" label, and the one place the adapter's refusals are explained. */
export function DemoBadge({ compact }: { compact: boolean }) {
  const { notification } = App.useApp();

  useEffect(() => {
    const onNotice = (event: Event) => {
      const kind = (event as CustomEvent<DemoNotice>).detail;
      const notice = NOTICES[kind];
      if (!notice) return;
      // Keyed: a page that fires five refused requests shows one notice, not five.
      notification.info({
        key: `demo-${kind}`,
        title: notice.title,
        description: (
          <Flex vertical gap={4}>
            <span>{notice.body}</span>
            {INSTALL_LINK}
          </Flex>
        ),
        placement: 'bottomRight',
        duration: 8,
      });
    };
    window.addEventListener(DEMO_NOTICE_EVENT, onNotice);
    return () => window.removeEventListener(DEMO_NOTICE_EVENT, onNotice);
  }, [notification]);

  return (
    <Flex align="center" gap={8} style={{ whiteSpace: 'nowrap' }}>
      <Tag color="gold" style={{ marginInlineEnd: 0 }}>
        {compact ? 'Demo' : 'Read-only demo · sample data'}
      </Tag>
      {!compact && <Typography.Text style={{ fontSize: 13 }}>{INSTALL_LINK}</Typography.Text>}
    </Flex>
  );
}

