// The pages the demo records and then replays. No Playwright import: the Vitest coverage test
// (tests/demo/routeCoverage.test.ts) reads ROUTE_PATTERNS to hold this list to the routers.

/** Every `<Route path>` the demo covers, parameters as `:id`. */
export const ROUTE_PATTERNS = [
  '/dashboard',
  '/assets',
  '/assets/:id',
  '/connections',
  '/connections/new',
  '/connections/:id/edit',
  '/suites',
  '/suites/new',
  '/suites/:id',
  '/suites/:id/edit',
  '/suites/:id/checks/new',
  '/suites/:id/checks/:id/edit',
  '/results',
  '/results/:id',
  '/profile',
  '/admin/overview',
  '/admin/members',
  '/admin/suites',
  '/admin/settings',
  '/admin/compliance',
  '/admin/integrations',
] as const;

type Row = { id: string };
/** Reads one API list (path under /api/v1) — live while recording, from the recording after. */
export type ListReader = (path: string) => Promise<Row[]>;

/** Expand the patterns into concrete URLs for every seeded suite, check, asset, run and connection. */
export async function discoverRoutes(list: ListReader): Promise<string[]> {
  const [suites, connections, assets, runs] = await Promise.all([
    list('/suites'),
    list('/connections'),
    list('/assets'),
    list('/runs'),
  ]);
  const checks = await Promise.all(
    suites.map(async (s) => ({ suite: s.id, checks: await list(`/suites/${s.id}/checks`) })),
  );
  const expand = (pattern: string): string[] => {
    switch (pattern) {
      case '/assets/:id':
        return assets.map((a) => `/assets/${a.id}`);
      case '/connections/:id/edit':
        return connections.map((c) => `/connections/${c.id}/edit`);
      case '/suites/:id':
      case '/suites/:id/edit':
      case '/suites/:id/checks/new':
        return suites.map((s) => pattern.replace(':id', s.id));
      case '/suites/:id/checks/:id/edit':
        return checks.flatMap((c) =>
          c.checks.map((check) => `/suites/${c.suite}/checks/${check.id}/edit`),
        );
      case '/results/:id':
        return runs.map((r) => `/results/${r.id}`);
      default:
        if (pattern.includes(':id')) throw new Error(`no expansion for ${pattern}`);
        return [pattern];
    }
  };
  return ROUTE_PATTERNS.flatMap(expand);
}
EOF
cat > e2e-demo/visit.ts <<'EOF'
import type { Page } from '@playwright/test';

import { settle } from '../scripts/a11y/settle';

/** Open a route and every tab on it, so the requests behind each tab are made. `route` is
 *  app-relative (`/suites/…`); it resolves under the project's baseURL, sub-path included. */
export async function visit(page: Page, route: string): Promise<void> {
  await page.goto(route.replace(/^\//, ''));
  await idle(page);
  const tabs = page.getByRole('tab');
  for (let i = 0; i < (await tabs.count()); i += 1) {
    const tab = tabs.nth(i);
    if (!(await tab.isVisible()) || (await tab.getAttribute('aria-disabled')) === 'true') continue;
    await tab.click();
    await idle(page);
  }
}

async function idle(page: Page): Promise<void> {
  // A polling page never goes network-idle for long; the spinner check below is the real gate.
  await page.waitForLoadState('networkidle', { timeout: 5_000 }).catch(() => undefined);
  await settle(page);
}
EOF
cat > e2e-demo/capture.spec.ts <<'EOF'
import { expect, test } from '@playwright/test';
import { writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { fixtureKey, type FixtureBundle, type RecordedResponse } from '../src/demo/fixtures';
import { discoverRoutes } from './routes';
import { visit } from './visit';

// Records what the app asks the API for on every route of the seeded workspace (#2419). The
// output, demo-fixtures.json, is never committed: CI records it from the stack it just seeded.
const OUT = resolve(dirname(fileURLToPath(import.meta.url)), '../demo-fixtures.json');
const API = '/api/v1';

test('record the seeded workspace', async ({ page }) => {
  test.setTimeout(15 * 60_000);
  const entries: Record<string, RecordedResponse> = {};
  const failures: string[] = [];
  const pending: Promise<void>[] = [];

  page.on('response', (response) => {
    const url = new URL(response.url());
    if (!url.pathname.startsWith(`${API}/`) || response.request().method() !== 'GET') return;
    const key = fixtureKey('GET', url.pathname + url.search);
    if (response.status() >= 500) failures.push(`${response.status()} ${key}`);
    pending.push(
      (async () => {
        const all = response.headers();
        if (!(all['content-type'] ?? '').includes('json')) return;
        const headers = Object.fromEntries(
          Object.entries(all).filter(([k]) => k.startsWith('x-') && k !== 'x-request-id'),
        );
        // A response whose page navigated away before its body was read is recorded on the
        // page that waits for it; losing this copy is fine.
        const data: unknown = await response.json().catch(() => undefined);
        if (data === undefined) return;
        entries[key] = { status: response.status(), data, headers };
      })(),
    );
  });

  const routes = await discoverRoutes(async (path) => {
    const response = await page.request.get(`${API}${path}`);
    expect(response.ok(), `GET ${path}`).toBe(true);
    return response.json();
  });
  for (const route of routes) await visit(page, route);
  await Promise.all(pending);

  expect(failures, 'the API answered 5xx while recording').toEqual([]);
  expect(Object.keys(entries).length).toBeGreaterThan(routes.length / 2);
  const bundle: FixtureBundle = { capturedAt: new Date().toISOString(), entries };
  writeFileSync(OUT, JSON.stringify(bundle));
  console.log(`recorded ${Object.keys(entries).length} responses over ${routes.length} routes`);
});
EOF

