1	/** What the demo could not do for the visitor — raised by the adapter, shown by `DemoBadge`. */
2	export type DemoNotice = 'read-only' | 'not-recorded' | 'approximate';
3	
4	/** Also dispatched on `window`, so a browser test can observe notices without the UI. */
5	export const DEMO_NOTICE_EVENT = 'dataq-demo-notice';
6	
7	type Listener = (kind: DemoNotice) => void;
8	const listeners = new Set<Listener>();
9	// The badge is a lazy chunk: a request can be refused before it has mounted.
10	const unseen = new Set<DemoNotice>();
11	
12	export function announce(kind: DemoNotice): void {
13	  window.dispatchEvent(new CustomEvent<DemoNotice>(DEMO_NOTICE_EVENT, { detail: kind }));
14	  if (listeners.size === 0) unseen.add(kind);
15	  else listeners.forEach((listener) => listener(kind));
16	}
17	
18	/** Receive notices, starting with any raised before there was a listener. */
19	export function subscribe(listener: Listener): () => void {
20	  listeners.add(listener);
21	  unseen.forEach((kind) => listener(kind));
22	  unseen.clear();
23	  return () => {
24	    listeners.delete(listener);
25	  };
26	}

